INSERT INTO "public"."documents" ("id", "content", "embedding", "metadata", "ingestion_date") VALUES
('122', 'Я приветствую вас на уроке «Здоровое питание как образ жизни». Я, наконец, расскажу, как сделать питание полезной привычкой на длительном протяжении времени. Итак, для начала забудьте о целях. Сейчас мы будем с вами строить фокус на систему. Ваша цель сейчас похудеть, а вот ваша система как питание входит в привычку, как сделать ее автоматизированной, как проходить срывы и как наладить режим. Почему важно забыть о Про цели. Цели ограничивают ваше счастье. Проблема мышления, ориентированного только на достижение цели, заключается в том, что вы постоянно откладываете счастье до следующего этапа в своей жизни. «Как только достигну отметки в 70 килограмм, вот тогда я почувствую себя желанной». Например. Не попадайте в эту ловушку. Только ориентация на цель принесёт вам просто какой-то конечный', '[-0.0031906632,-0.027203996,-0.0017333062,0.007628847,0.015108221,-0.046842385,-0.0039322767,0.038310952,-0.014475837,-0.029066654,0.0050360737,0.0032481526,0.029986484,0.0010808012,-0.023122247,-0.016591448,-0.011394404,-0.015637124,0.013119087,-0.044979725,0.028261801,-0.0369542,-0.032056104,-0.012900627,-0.007623098,0.010543561,0.01299261,0.03511454,-0.020040814,-0.03217108,-0.029710535,0.044657785,-0.022248408,0.019281954,-0.032975934,-0.016464971,0.014441344,-0.020316763,-0.013199572,0.049394913,-0.013556006,0.016487967,0.0068297437,0.04203627,0.015763601,0.028606739,0.018856531,-0.0027422456,0.0386099,-0.0418753,0.008117507,-0.0041248663,0.050912637,-0.025042394,0.03959872,0.009439764,0.03338986,-0.020500729,0.0035873402,0.033136904,-0.039782684,0.01538417,-0.026951043,-0.03854091,-0.03398775,-0.032263067,-0.006933225,0.056799553,0.017223831,0.04284112,-0.010365344,-0.0029492076,-0.02697404,-0.032194078,-0.0195694,-0.06618182,0.0007236482,-0.005567851,0.01930495,-0.048935,-0.025801254,0.016901892,0.016108537,-0.012889129,0.07818562,-0.025571296,0.020776678,-0.04550863,-0.0024203048,0.0029750778,-0.027135009,-0.011992294,-0.017039865,-0.003751185,-0.0054126293,0.0